ype.GetField("lockpickAnglePrecision", flags)?.GetValue(openable), culture); var building = behaviour.GetComponent("BuildingEntity"); var health = -1f; if (building != null) { var healthType = building.GetType(); System.Reflection.PropertyInfo healthProperty = null; while (healthType != null && healthProperty == null) { healthProperty = healthType.GetProperty("health", flags); healthType = healthType.BaseType; } if (healthProperty != null) { health = System.Convert.ToSingle(healthProperty.GetValue(building), culture); } else { healthType = building.GetType(); System.Reflection.FieldInfo healthField = null; while (healthType != null && healthField == null) { healthField = healthType.GetField("_health", flags) ?? healthType.GetField("health", flags); healthType = healthType.BaseType; } if (healthField != null) { health = System.Convert.ToSingle(healthField.GetValue(building), culture); } } } var position = behaviour.transform.position; var distance = UnityEngine.Vector2.Distance(new UnityEngine.Vector2(bodyPos.x, bodyPos.y), new UnityEngine.Vector2(position.x, position.y)); if (count > 0) { doors.Append(", "); } doors.Append("{\"x\":" + position.x.ToString("0.###", culture) + ",\"y\":" + position.y.ToString("0.###", culture) + ",\"distance\":" + distance.ToString("0.##", culture) + ",\"instant\":" + (instant ? "true" : "false") + ",\"keypad\":" + (keypad ? "true" : "false") + ",\"precision\":" + precision.ToString("0.###", culture) + ",\"health\":" + health.ToString("0.##", culture) + "}"); count++; if (count >= 40) { break; } } return "{\"ok\":true,\"count\":" + count.ToString(culture) + ",\"bodyX\":" + bodyPos.x.ToString("0.###", culture) + ",\"bodyY\":" + bodyPos.y.ToString("0.###", culture) + ",\"doors\":[" + doors.ToString() + "]}"; }))()
